import {
  baseConfigSchema,
  databaseConfigSchema,
  databaseReadConfigSchema,
  httpConfigSchema,
  loadConfig,
  notifySmtpFieldsSchema,
  redisConfigSchema,
  s3ConfigSchema,
  validateNotifySmtpConfig,
} from '@email-gateway/config';
import { z } from 'zod';

const int = (min: number, max = Number.MAX_SAFE_INTEGER) =>
  z.coerce.number().int().min(min).max(max);
const bool = z.enum(['true', 'false', '1', '0']).transform((v) => v === 'true' || v === '1');
/** Shared secrets (HMAC/JWT keys). Generated by `pnpm env:init` as 64 hex characters. */
const secret = z.string().min(64, 'must be at least 64 characters');
/** AES-256 key: exactly 32 bytes as 64 hex characters. */
const aesKey = z.string().regex(/^[0-9a-fA-F]{64}$/, 'must be exactly 64 hex characters');

/** Authentication, sessions and tenancy (design D15 of steps 1.2/1.3). */
const authConfigShape = {
  AUTH_JWT_SECRET: secret,
  /** Accepted for verification only, while rotating AUTH_JWT_SECRET. */
  AUTH_JWT_PREVIOUS_SECRET: secret.optional(),
  AUTH_JWT_ISSUER: z.string().min(1).default('email-gateway'),
  AUTH_JWT_AUDIENCE: z.string().min(1).default('email-gateway-api'),
  AUTH_ACCESS_TOKEN_TTL_SECONDS: int(60, 900).default(600),
  /** Sliding idle lifetime of a session's refresh token. */
  AUTH_REFRESH_TOKEN_TTL_SECONDS: int(3600).default(604800),
  /** Absolute session lifetime; refresh never extends a session past it. */
  AUTH_SESSION_MAX_AGE_SECONDS: int(3600).default(2592000),
  /** HMAC key for API-key and recovery-code hashes. */
  AUTH_TOKEN_PEPPER: secret,
  /** AES-256-GCM key for application-encrypted columns (MFA secrets). */
  DATA_ENCRYPTION_KEY: aesKey,
  /** Accepted for decryption only, while rotating DATA_ENCRYPTION_KEY. */
  DATA_ENCRYPTION_KEY_PREVIOUS: aesKey.optional(),
  // OWASP Password Storage Cheat Sheet floor for Argon2id; configurable upward only.
  AUTH_ARGON2_MEMORY_KIB: int(19456, 1048576).default(19456),
  AUTH_ARGON2_TIME_COST: int(2, 20).default(2),
  AUTH_ARGON2_PARALLELISM: int(1, 16).default(1),
  AUTH_LOGIN_MAX_ACCOUNT_FAILURES: int(1, 100).default(5),
  AUTH_LOGIN_MAX_IP_FAILURES: int(1, 10000).default(50),
  AUTH_LOGIN_FAILURE_WINDOW_SECONDS: int(60, 86400).default(900),
  AUTH_LOCKOUT_BASE_SECONDS: int(1, 86400).default(900),
  AUTH_LOCKOUT_MAX_SECONDS: int(1, 2592000).default(86400),
  AUTH_MFA_ISSUER: z
    .string()
    .min(1)
    .max(64)
    .regex(/^[^:]+$/, 'must not contain ":"')
    .default('EmailSecurityGateway'),
  AUTH_PASSWORD_RESET_TTL_SECONDS: int(300, 86400).default(1800),
  AUTH_EMAIL_VERIFICATION_TTL_SECONDS: int(300, 604800).default(86400),
  AUTH_INVITATION_TTL_SECONDS: int(3600, 2592000).default(604800),
  AUTH_LOGIN_AUDIT_RETENTION_DAYS: int(1, 3650).default(365),
  /** Hourly session/token/login-audit purge. Disabled in tests. */
  AUTH_BACKGROUND_JOBS_ENABLED: bool.default(true),
  PLATFORM_OVERRIDE_MAX_MINUTES: int(5, 240).default(60),
  ORG_DELETION_RETENTION_DAYS: int(7, 3650).default(30),
  ORG_DELETION_CONFIRM_WINDOW_HOURS: int(1, 720).default(72),
  /** Express `trust proxy` hop count: 0 locally, 1 behind the ALB/ingress. Drives `req.ip`. */
  HTTP_TRUST_PROXY: int(0, 10).default(0),
  /** Origin of the admin portal; links in emails point at `${PORTAL_PUBLIC_URL}/auth/...`. */
  PORTAL_PUBLIC_URL: z
    .url({ protocol: /^https?$/ })
    .transform((v) => v.replace(/\/+$/, ''))
    .default('http://localhost:3001'),
};

export const apiConfigSchema = baseConfigSchema
  .extend(httpConfigSchema(3000).shape)
  .extend(databaseConfigSchema.shape)
  // Control plane only: list/search/report reads may use the replica (ADR-0014).
  .extend(databaseReadConfigSchema.shape)
  .extend(redisConfigSchema.shape)
  .extend(s3ConfigSchema.shape)
  .extend(notifySmtpFieldsSchema.shape)
  .extend(authConfigShape)
  .extend({
    /** Comma-separated allow-list of admin portal origins. */
    CORS_ORIGINS: z
      .string()
      .default('')
      .transform((v) =>
        v
          .split(',')
          .map((o) => o.trim())
          .filter(Boolean),
      ),
  })
  .superRefine((cfg, ctx) => {
    validateNotifySmtpConfig(cfg, ctx);
    if (cfg.AUTH_SESSION_MAX_AGE_SECONDS < cfg.AUTH_REFRESH_TOKEN_TTL_SECONDS) {
      ctx.addIssue({
        code: 'custom',
        path: ['AUTH_SESSION_MAX_AGE_SECONDS'],
        message: 'must be greater than or equal to AUTH_REFRESH_TOKEN_TTL_SECONDS',
      });
    }
    if (
      (cfg.APP_ENV === 'staging' || cfg.APP_ENV === 'production') &&
      !cfg.PORTAL_PUBLIC_URL.startsWith('https://')
    ) {
      ctx.addIssue({
        code: 'custom',
        path: ['PORTAL_PUBLIC_URL'],
        message: 'must be an https:// URL when APP_ENV is staging or production',
      });
    }
    if (cfg.AUTH_LOCKOUT_MAX_SECONDS < cfg.AUTH_LOCKOUT_BASE_SECONDS) {
      ctx.addIssue({
        code: 'custom',
        path: ['AUTH_LOCKOUT_MAX_SECONDS'],
        message: 'must be greater than or equal to AUTH_LOCKOUT_BASE_SECONDS',
      });
    }
  });

export type ApiConfig = z.infer<typeof apiConfigSchema>;

export const loadApiConfig = (env: NodeJS.ProcessEnv = process.env): Readonly<ApiConfig> =>
  loadConfig(apiConfigSchema, env);
